// Select canvas element and get 2D context
const canvas = document.querySelector("canvas");
const ctx = canvas.getContext("2d");

// Set fixed canvas dimensions
const CANVAS_WIDTH = 500;
const CANVAS_HEIGHT = 500;
canvas.width = CANVAS_WIDTH;
canvas.height = CANVAS_HEIGHT;

// Animation variables
let currentAngle = 0.04; // Starting angle for heart shape
let angleIncrement = -0.07; // Speed and direction of angle change
let patternFrequency = 5; // Frequency of the surrounding pattern
let isClockwise = true; // Direction of rotation

// Function to draw and animate the heart
function drawHeart() {
  // Update angle for animation
  currentAngle += angleIncrement;

  // Calculate heart's center point using parametric equations
  const heartX =
    CANVAS_WIDTH / 2 +
    ((CANVAS_WIDTH - 25) / 2) * Math.pow(Math.sin(currentAngle), 3);
  const heartY =
    CANVAS_HEIGHT / 2 -
    13 *
      (13 * Math.cos(currentAngle) -
        5 * Math.cos(2 * currentAngle) -
        2 * Math.cos(3 * currentAngle));

  // Start drawing the pattern around the heart
  ctx.beginPath();
  ctx.moveTo(heartX, heartY);

  // Set random color for the stroke
  const randomHue = Math.random() * 360;
  ctx.strokeStyle = `hsl(${randomHue}, 100%, 50%)`; // Vibrant, random color

  // Draw the circular pattern around the heart
  for (let t = 0; t < 2 * Math.PI; t += 0.01) {
    const offsetX = heartX + 8 * Math.cos(patternFrequency * t) * Math.cos(t);
    const offsetY = heartY + 8 * Math.cos(patternFrequency * t) * Math.sin(t);
    ctx.lineTo(offsetX, offsetY);
  }
  ctx.stroke();
  ctx.closePath();

  // Draw a line from canvas center to heart position
  ctx.beginPath();
  ctx.moveTo(CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); // Center of canvas
  ctx.lineTo(heartX, heartY); // Heart's current position
  ctx.stroke();
  ctx.closePath();

  // Reverse direction when angle exceeds bounds
  if (currentAngle < -Math.PI * 2 || currentAngle > Math.PI * 2) {
    isClockwise = !isClockwise; // Toggle direction
    angleIncrement = isClockwise ? 0.05 : -0.07; // Adjust speed based on direction
    currentAngle = 0.04; // Reset angle
  }

  // Continue animation
  requestAnimationFrame(drawHeart);
}

// Start the animation
requestAnimationFrame(drawHeart);
